SELECT external_id, display_title, icon_key, description, latest_version, source, created_at, updated_at FROM filtered WHERE source = #{query.Source} ORDER BY
display_title ASC, external_id ASC updated_at DESC, external_id ASC CASE WHEN source = 'anthropic' THEN 0 ELSE 1 END, created_at DESC, external_id ASC
LIMIT #{query.Limit} OFFSET #{query.Offset}
